q10 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$An integration test sits in the middle layer of the pyramid. What trade-off does it represent compared with a unit test?$qz$, 'multiple_choice', 10 from newq returning id),
