newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A test for a login flow ends with `await expect(page).not.toHaveURL('/login')`. Why is this a weak assertion?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Because `not` is never allowed in assertions$qz$, false), ($qz$Because leaving `/login` does not confirm the user actually reached the authenticated area — an error page would also pass$qz$, true), ($qz$Because URLs cannot be asserted on in Playwright$qz$, false), ($qz$Because it checks too many things at once$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Which assertion most meaningfully verifies that "adding an item updates the cart total"?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$`await expect(page.getByTestId('cart')).toBeVisible()`$qz$, false), ($qz$`await expect(page.getByTestId('cart-total')).toHaveText('£24.00')`$qz$, true), ($qz$`await expect(page).toHaveTitle(/Shop/)`$qz$, false), ($qz$`await expect(addButton).toBeEnabled()`$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Look at this test:
~~~ts
test('creates an order', async ({ page }) => {
  await page.goto('/orders/new');
  await page.getByRole('button', { name: 'Create' }).click();
  expect(true).toBe(true);
});
~~~
Why is it green-but-useless?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Because it never navigates anywhere$qz$, false), ($qz$Because its only assertion checks a constant, so it can never fail regardless of whether the order was created$qz$, true), ($qz$Because `getByRole` is the wrong locator$qz$, false), ($qz$Because tests must not click buttons$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$What is the main risk of an assertion like `await expect(rows).toHaveCount(0)` immediately after loading a list that is populated asynchronously?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$There is no risk; zero is always correct$qz$, false), ($qz$It may pass simply because the rows have not rendered yet, so it can assert "empty" on a list that will shortly be full$qz$, true), ($qz$`toHaveCount` cannot take the value 0$qz$, false), ($qz$Counting rows is not supported by Playwright$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A meaningful test typically follows an arrange–act–assert structure. What is the "act" step verifying quality of, if the "assert" is vague?$qz$, 'multiple_choice', 5 from newq returning id),
a5 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q5.id, v.t, v.c from q5, (values ($qz$Nothing — a vague assertion undermines the whole test, because the act can succeed or fail without the assertion noticing$qz$, true), ($qz$The act step is unaffected; assertions are optional$qz$, false), ($qz$A vague assertion makes the act step run faster$qz$, false), ($qz$The act step automatically compensates for a weak assertion$qz$, false)) as v(t, c) returning question_id),
q6 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Which change turns a weak "smoke" check into a meaningful behavioural test for a search feature?$qz$, 'multiple_choice', 6 from newq returning id),
a6 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q6.id, v.t, v.c from q6, (values ($qz$Assert only that the search page loaded$qz$, false), ($qz$Search for a known term and assert that a result containing that term appears and an unrelated result does not$qz$, true), ($qz$Assert that the search box is present on the page$qz$, false), ($qz$Assert that the page title contains the word "Search"$qz$, false)) as v(t, c) returning question_id),
q7 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A test asserts `await expect(page.locator('body')).toContainText('Success')`. Why might this pass even when the wrong success message is shown?$qz$, 'multiple_choice', 7 from newq returning id),
a7 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q7.id, v.t, v.c from q7, (values ($qz$Because `toContainText` matches anywhere in the body, so any element containing the substring — including an unrelated banner — satisfies it$qz$, true), ($qz$Because `body` is not a valid locator$qz$, false), ($qz$Because `toContainText` ignores case and therefore always passes$qz$, false), ($qz$Because the assertion targets the wrong page$qz$, false)) as v(t, c) returning question_id),
q8 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$You inherit a suite where every test ends with a screenshot and no assertions, described as "visual coverage". What is the core problem?$qz$, 'multiple_choice', 8 from newq returning id),
a8 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q8.id, v.t, v.c from q8, (values ($qz$Screenshots are too large to store$qz$, false), ($qz$Nothing is being verified automatically — a human would have to inspect every screenshot for the suite to catch anything$qz$, true), ($qz$Screenshots cannot be captured in headless mode$qz$, false), ($qz$There is no problem; screenshots are equivalent to assertions$qz$, false)) as v(t, c) returning question_id),
q9 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Which of these is the strongest sign a test is actually testing something?$qz$, 'multiple_choice', 9 from newq returning id),
a9 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q9.id, v.t, v.c from q9, (values ($qz$It has a long, descriptive title$qz$, false), ($qz$Deliberately breaking the feature it covers makes the test fail$qz$, true), ($qz$It runs quickly$qz$, false), ($qz$It contains many `await` calls$qz$, false)) as v(t, c) returning question_id),
q10 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A test verifies a discount by asserting the discounted price is "less than the original". Why might a designer of meaningful tests still object?$qz$, 'multiple_choice', 10 from newq returning id),
a10 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q10.id, v.t, v.c from q10, (values ($qz$Because "less than" is impossible to express in code$qz$, false), ($qz$Because a wildly wrong discount (for example, a penny off, or a negative total) would also be "less than the original" and slip through$qz$, true), ($qz$Because prices should never be compared$qz$, false), ($qz$Because the test needs a screenshot to be valid$qz$, false)) as v(t, c) returning question_id),
q11 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Two tests give the same confidence, but one asserts the exact expected value and the other asserts only that a field is "not empty". Which is preferable and why?$qz$, 'multiple_choice', 11 from newq returning id),
a11 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q11.id, v.t, v.c from q11, (values ($qz$The "not empty" one, because it is more flexible and rarely fails$qz$, false), ($qz$The exact-value one, because it will catch a wrong-but-present value that the looser check would let through$qz$, true), ($qz$They are identical, so it does not matter$qz$, false), ($qz$The "not empty" one, because exact assertions are always brittle and should be avoided$qz$, false)) as v(t, c) returning question_id)
select 1;

with m as (select mo.id from public.modules mo join public.courses c on c.id = mo.course_id where c.slug = 'modern-test-automation-bootcamp' and mo.module_number = 6),
newq as (insert into public.quizzes (module_id, title, pass_mark) select id, $qz$Reflection & Knowledge Check$qz$, 70 from m where not exists (select 1 from public.quizzes where module_id = (select id from m)) returning id),
q1 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A test does `await page.waitForTimeout(2000)` before checking a result, and it still fails on a slow CI runner. What is the underlying problem with this approach?$qz$, 'multiple_choice', 1 from newq returning id),
a1 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q1.id, v.t, v.c from q1, (values ($qz$Two seconds is simply too short; five seconds would fix it permanently$qz$, false), ($qz$A fixed sleep guesses at timing rather than waiting for the actual condition, so it is both slow and unreliable across environments$qz$, true), ($qz$`waitForTimeout` is not a real Playwright method$qz$, false), ($qz$The problem is the assertion, not the wait$qz$, false)) as v(t, c) returning question_id),
q2 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Which replacement removes a hard wait correctly before reading a total?$qz$, 'multiple_choice', 2 from newq returning id),
a2 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q2.id, v.t, v.c from q2, (values ($qz$`await page.waitForTimeout(1000)` then read the total$qz$, false), ($qz$`await expect(page.getByTestId('total')).toHaveText('£30.00')`$qz$, true), ($qz$`for (let i = 0; i < 100; i++) {}` then read the total$qz$, false), ($qz$Remove the wait entirely and hope the value is ready$qz$, false)) as v(t, c) returning question_id),
q3 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$A test passes locally but flakes on CI roughly one run in five. Which investigation step is most productive first?$qz$, 'multiple_choice', 3 from newq returning id),
a3 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q3.id, v.t, v.c from q3, (values ($qz$Add `retries: 5` and consider it solved$qz$, false), ($qz$Reproduce and diagnose it — use the trace, video, or repeated runs to find the race condition or timing assumption behind the intermittent failure$qz$, true), ($qz$Delete the test, since flaky tests are worthless$qz$, false), ($qz$Increase every timeout in the config to ten minutes$qz$, false)) as v(t, c) returning question_id),
q4 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Which of these is a classic cause of flakiness in browser automation?$qz$, 'multiple_choice', 4 from newq returning id),
a4 as (insert into public.quiz_answers (question_id, answer_text, is_correct) select q4.id, v.t, v.c from q4, (values ($qz$Using `getByRole` locators$qz$, false), ($qz$Asserting on an element or reading state before the application has finished updating it$qz$, true), ($qz$Setting a `baseURL` in the config$qz$, false), ($qz$Writing tests in TypeScript rather than JavaScript$qz$, false)) as v(t, c) returning question_id),
q5 as (insert into public.quiz_questions (quiz_id, question_text, question_type, sort_order) select id, $qz$Consider this flaky snippet:
~~~ts
